using Logic.Contracts;

namespace Logic.CollisionResolution;

/// <summary>
/// A simple collision resolution strategy that appends the attempt number as a suffix to the base short URL.
/// This strategy is suitable for single-instance deployments or when collision probability is low.
/// </summary>
public class SuffixCollisionResolutionStrategy : ICollisionResolutionStrategy
{
    /// <summary>
    /// Generates a unique short URL by appending the attempt number as a suffix.
    /// </summary>
    /// <param name="baseShortUrl">The base short URL generated by the primary shortener.</param>
    /// <param name="attempt">The current attempt number (0-based).</param>
    /// <param name="longUrl">The original long URL being shortened.</param>
    /// <returns>A unique short URL with attempt number suffix.</returns>
    public string GenerateUniqueShortUrl(string baseShortUrl, int attempt, string longUrl)
    {
        ArgumentException.ThrowIfNullOrEmpty(baseShortUrl);
        ArgumentException.ThrowIfNullOrEmpty(longUrl);

        if (attempt < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(attempt), "Attempt number must be non-negative.");
        }

        // For attempt 0, return the base short URL (deterministic)
        if (attempt == 0)
        {
            return baseShortUrl;
        }

        // For retry attempts, append the attempt number as a suffix
        return $"{baseShortUrl}_{attempt}";
    }
}
